files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1c2c;
  --panel: #29366f;
  --accent: #ffcd75;
  --accent-dark: #e0a83a;
  --text: #f4f4f4;
  --muted: #a7b1d8;
  --danger: #b13e53;
  --radius: 10px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--bg);
  background-image:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--panel);
  border: 4px solid #10121f;
  border-radius: var(--radius);
  box-shadow: 0 8px 0 #10121f, 0 12px 30px rgba(0,0,0,0.5);
  padding: 28px 22px 24px;
  text-align: center;
}

.title {
  margin: 0 0 20px;
  font-size: 1.4rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #10121f;
}

.mode-switch {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin-bottom: 16px;
}

.mode-btn {
  flex: 1;
  padding: 10px 8px;
  font-size: 1rem;
  font-weight: 700;
  color: var(--muted);
  background: #1f2a55;
  border: 3px solid #10121f;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease, color 0.15s ease;
}

.mode-btn:hover { background: #26346b; color: var(--text); }
.mode-btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.mode-btn:active { transform: translateY(2px); }

.mode-btn.active {
  background: var(--accent);
  color: #10121f;
  border-color: var(--accent-dark);
}

.mode-label {
  margin: 0 0 6px;
  font-size: 1rem;
  color: var(--muted);
  letter-spacing: 0.5px;
}

.display {
  font-family: "Courier New", monospace;
  font-size: clamp(3.5rem, 22vw, 6rem);
  font-weight: 700;
  line-height: 1;
  color: var(--accent);
  text-shadow: 4px 4px 0 #10121f;
  margin: 10px 0 24px;
  padding: 10px 4px;
  background: #161a33;
  border: 4px solid #10121f;
  border-radius: 8px;
  user-select: none;
}

.display.break-mode {
  color: #a7f070;
}

.controls {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 0;
  min-width: 90px;
  padding: 12px 10px;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  background: #3b4a8a;
  border: 3px solid #10121f;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease;
}

.btn:hover { background: #4a5ca8; }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn:active { transform: translateY(2px); }

.btn.primary {
  background: var(--accent);
  color: #10121f;
  border-color: var(--accent-dark);
}

.btn.primary:hover { background: #ffd98f; }

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.status {
  margin: 18px 0 0;
  font-size: 1rem;
  color: var(--muted);
  min-height: 1.4em;
}

@media (max-width: 380px) {
  body { padding: 12px; }
  .card { padding: 22px 14px 18px; }
  .btn { min-width: 70px; }
}

(function () {
  'use strict';

  var WORK_MS = 25 * 60 * 1000;
  var BREAK_MS = 5 * 60 * 1000;

  var display = document.getElementById('display');
  var modeLabel = document.getElementById('mode-label');
  var statusEl = document.getElementById('status');
  var startBtn = document.getElementById('start-btn');
  var pauseBtn = document.getElementById('pause-btn');
  var resetBtn = document.getElementById('reset-btn');
  var workBtn = document.getElementById('work-btn');
  var breakBtn = document.getElementById('break-btn');

  var mode = 'work';
  var remaining = WORK_MS;
  var running = false;
  var endTime = 0;
  var tickId = null;

  function durationFor(m) {
    return m === 'work' ? WORK_MS : BREAK_MS;
  }

  function formatTime(ms) {
    var totalSeconds = Math.ceil(ms / 1000);
    if (totalSeconds < 0) totalSeconds = 0;
    var minutes = Math.floor(totalSeconds / 60);
    var seconds = totalSeconds % 60;
    return (minutes < 10 ? '0' : '') + minutes + ':' + (seconds < 10 ? '0' : '') + seconds;
  }

  function render() {
    display.textContent = formatTime(remaining);
    display.classList.toggle('break-mode', mode === 'break');
    modeLabel.textContent = mode === 'work' ? 'Work session' : 'Break session';
    workBtn.classList.toggle('active', mode === 'work');
    breakBtn.classList.toggle('active', mode === 'break');
    workBtn.setAttribute('aria-pressed', String(mode === 'work'));
    breakBtn.setAttribute('aria-pressed', String(mode === 'break'));
    startBtn.disabled = running;
    pauseBtn.disabled = !running;
  }

  function setStatus(text) {
    statusEl.textContent = text;
  }

  function tick() {
    remaining = endTime - Date.now();
    if (remaining <= 0) {
      remaining = 0;
      stopTimer();
      render();
      setStatus(mode === 'work' ? 'Work session complete! Take a break.' : 'Break over! Back to work.');
      return;
    }
    render();
  }

  function startTimer() {
    if (running) return;
    if (remaining <= 0) remaining = durationFor(mode);
    running = true;
    endTime = Date.now() + remaining;
    tickId = setInterval(tick, 250);
    render();
    setStatus('Running');
  }

  function stopTimer() {
    running = false;
    if (tickId !== null) {
      clearInterval(tickId);
      tickId = null;
    }
  }

  function pauseTimer() {
    if (!running) return;
    remaining = Math.max(0, endTime - Date.now());
    stopTimer();
    render();
    setStatus('Paused');
  }

  function resetTimer() {
    stopTimer();
    remaining = durationFor(mode);
    render();
    setStatus('Ready');
  }

  function setMode(newMode) {
    if (mode === newMode) return;
    mode = newMode;
    stopTimer();
    remaining = durationFor(mode);
    render();
    setStatus('Ready');
  }

  startBtn.addEventListener('click', startTimer);
  pauseBtn.addEventListener('click', pauseTimer);
  resetBtn.addEventListener('click', resetTimer);
  workBtn.addEventListener('click', function () { setMode('work'); });
  breakBtn.addEventListener('click', function () { setMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target && (e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT')) return;
    if (e.code === 'Space') {
      e.preventDefault();
      if (running) pauseTimer(); else startTimer();
    } else if (e.key === 'r' || e.key === 'R') {
      resetTimer();
    }
  });

  render();
})();
